starter.css:
.wrap {
  width: 600px; /* the checks change this width */
}
.session-card {
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}
.session-card h3 { margin: 8px 0; }
.badge {
  display: block;
  padding: 0.1em 0.6em;
  border-radius: 999px;
  background: #fee2e2;
  color: #991b1b;
}

.session-card { padding: 24px; }
.abstract { width: 40ch; }

solution.css:
.wrap {
  width: 600px; /* the checks change this width */
}
.session-card {
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}
.session-card h3 { margin: 8px 0; }
.badge {
  display: block;
  padding: 0.1em 0.6em;
  border-radius: 999px;
  background: #fee2e2;
  color: #991b1b;
}

.session-card { padding: clamp(12px, 4%, 32px); }
.abstract { width: min(100%, 40ch); }
.badge { width: fit-content; }
